", "thought": true, "video_metadata": null, "tool_call": null, "tool_response": null}, {"media_resolution": null, "code_execution_result": null, "executable_code": null, "file_data": null, "function_call": null, "function_response": null, "inline_data": null, "text": "Le hulan nita kina, yami laka ena palahi laloita le pondokan. Sile lane kula maul nyela, laha yami malaa malaan. Usia yami palahi sile, yami apiri laha maluhu, yami laka le luma ena supu lawang.", "thought": null, "video_metadata": null, "tool_call": null, "tool_response": null}], "role": "model"}, "citation_metadata": null, "finish_message": null, "token_count": null, "finish_reason": "STOP", "grounding_metadata": null, "avg_logprobs": null, "index": 0, "logprobs_result": null, "safety_ratings": null, "url_context_metadata": null}], "create_time": null, "model_version": "gemini-3.5-flash", "prompt_feedback": null, "response_id": "NfawavT-O_qDmtkPktbj4QI", "usage_metadata": {"cache_tokens_details": null, "cached_content_token_count": null, "candidates_token_count": 69, "candidates_tokens_details": null, "prompt_token_count": 19968, "prompt_tokens_details": [{"modality": "TEXT", "token_count": 19968}], "thoughts_token_count": 4013, "tool_use_prompt_token_count": null, "tool_use_prompt_tokens_details": null, "total_token_count": 24050, "traffic_type": null}, "automatic_function_calling_history": [], "parsed": null}

